// EXPORTS: useSeasonalTheme
import { useState, useEffect, useMemo, useCallback } from 'react'
import { scopedStorage } from '@lark-apaas/client-toolkit-lite'
import { getSeason, getThemeConfig, getFestivalBadge, type ThemeConfig, type FestivalBadge, type Season } from '@/lib/theme'

const STORAGE_KEY = 'seasonal-theme-override'

type ThemeOverride = Season | 'auto'

function readOverride(): ThemeOverride {
  try {
    const val = scopedStorage.getItem(STORAGE_KEY)
    if (val === 'spring' || val === 'summer' || val === 'autumn' || val === 'winter' || val === 'auto') {
      return val
    }
  } catch { /* noop */ }
  return 'auto'
}

export function useSeasonalTheme() {
  const [now, setNow] = useState(new Date())
  const [override, setOverride] = useState<ThemeOverride>(() => readOverride())

  useEffect(() => {
    const timer = setInterval(() => setNow(new Date()), 60000)
    return () => clearInterval(timer)
  }, [])

  const theme: ThemeConfig = useMemo(() => {
    if (override === 'auto') {
      const season = getSeason(now.getMonth() + 1)
      return getThemeConfig(season)
    }
    return getThemeConfig(override)
  }, [now, override])

  const festival: FestivalBadge = useMemo(() => {
    return getFestivalBadge(now.getMonth() + 1, now.getDate(), now.getDay())
  }, [now])

  const setThemeOverride = useCallback((value: ThemeOverride) => {
    setOverride(value)
    try {
      scopedStorage.setItem(STORAGE_KEY, value)
    } catch { /* noop */ }
  }, [])

  return { theme, festival, now, themeOverride: override, setThemeOverride }
}
