import { createContext, useContext, useState, useEffect, useCallback, type ReactNode } from 'react';
import { scopedStorage, logger } from '@lark-apaas/client-toolkit-lite';
import api, { AUTH_EXPIRED_EVENT, clearAuthStorage } from '@/lib/api';

const TOKEN_KEY = 'auth_token';
const USER_KEY = 'auth_user';
const ACCOUNTS_KEY = 'xinzhihai_accounts';

export interface AuthAccountRecord {
  id: number;
  username: string;
  nickname: string;
  role: 'user' | 'sub_account' | 'admin' | 'super_admin';
  password?: string;
  register_at: string;
  last_login_at: string;
  status: 'active' | 'disabled' | 'pending' | 'rejected';
  parent_username?: string;
}

export function _readAccounts(): AuthAccountRecord[] {
  try {
    const raw = scopedStorage.getItem(ACCOUNTS_KEY);
    if (!raw) return [];
    const arr = JSON.parse(raw);
    return Array.isArray(arr) ? arr : [];
  } catch (e) {
    logger.warn('读取账号列表失败', String(e));
    return [];
  }
}

export function _writeAccounts(accounts: AuthAccountRecord[]) {
  try {
    scopedStorage.setItem(ACCOUNTS_KEY, JSON.stringify(accounts));
  } catch (e) {
    logger.warn('写入账号列表失败', String(e));
  }
}

/**
 * 注册账号时写入账号列表；若用户名已存在则更新最后登录时间。
 * 同时记录密码用于本地降级模式登录校验。
 */
export function upsertAccount(record: AuthAccountRecord) {
  const accounts = _readAccounts();
  const idx = accounts.findIndex(a => a.username === record.username);
  if (idx >= 0) {
    accounts[idx] = { ...accounts[idx], ...record };
  } else {
    accounts.push(record);
  }
  _writeAccounts(accounts);
}

/**
 * 更新账号的最后登录时间
 */
export function touchAccountLogin(username: string) {
  const accounts = _readAccounts();
  const idx = accounts.findIndex(a => a.username === username);
  if (idx >= 0) {
    accounts[idx].last_login_at = new Date().toISOString();
    _writeAccounts(accounts);
  }
}

/**
 * 读取全部账号列表
 */
export function getAllAccounts(): AuthAccountRecord[] {
  return _readAccounts();
}

/**
 * 删除本地账号记录（按用户名）
 */
export function removeAccount(username: string) {
  const accounts = _readAccounts();
  const filtered = accounts.filter(a => a.username !== username);
  _writeAccounts(filtered);
}

/**
 * 本地校验账号密码（降级模式用）
 */
export function verifyLocalAccount(username: string, password: string): AuthAccountRecord | null {
  const accounts = _readAccounts();
  const acc = accounts.find(a => a.username === username);
  if (!acc) return null;
  // 若账号列表里有密码则校验；没有则兼容旧数据，直接通过
  if (acc.password && acc.password !== password) return null;
  if (acc.status === 'disabled') return null;
  if (acc.status === 'pending') return null;
  if (acc.status === 'rejected') return null;
  return acc;
}

export function getAccountStatus(username: string): string | null {
  const accounts = _readAccounts();
  const acc = accounts.find(a => a.username === username);
  return acc?.status ?? null;
}

export interface AuthUser {
  id: number;
  username: string;
  nickname: string;
  role: 'user' | 'sub_account' | 'admin' | 'super_admin';
  parentId?: number;
}

interface AuthContextValue {
  user: AuthUser | null;
  token: string | null;
  isLoggedIn: boolean;
  isLoading: boolean;
  login: (username: string, password: string) => Promise<void>;
  register: (username: string, password: string, nickname?: string) => Promise<{ autoLoggedIn: boolean }>;
  logout: () => Promise<void>;
  refreshUser: () => Promise<void>;
  approveAccount: (username: string, adminUsername?: string) => Promise<{ success: boolean; error?: string }>;
  rejectAccount: (username: string, adminUsername?: string) => Promise<{ success: boolean; error?: string }>;
  updateAccountPassword: (accountId: number, newPassword: string) => Promise<boolean | 'local'>;
}

const AuthContext = createContext<AuthContextValue | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [token, setToken] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // 初始化：从本地存储恢复登录态，并校验 token 有效性
  useEffect(() => {
    const savedToken = scopedStorage.getItem(TOKEN_KEY);
    const savedUser = scopedStorage.getItem(USER_KEY);
    if (savedToken && savedUser) {
      try {
        let parsed = JSON.parse(savedUser) as AuthUser;
        // wuxin209 超级主账号白名单：刷新后也保持 super_admin 权限
        if (parsed.username === 'wuxin209') {
          parsed = { ...parsed, role: 'super_admin' };
        }
        setToken(savedToken);
        setUser(parsed);

        // 本地 token 恢复后，异步校验有效性（401 会被响应拦截器自动清态）
        // 不 await：避免阻塞首屏渲染，后台静默校验
        api.get('/auth/me').catch((err) => {
          const status = err?.response?.status;
          if (status === 401) {
            logger.info('[auth] 启动时 token 校验失败，已清态');
          } else {
            logger.warn('[auth] 启动时 /auth/me 请求失败，但 token 本地仍有效', String(err?.message || err));
          }
        });
      } catch (e) {
        logger.warn('本地用户数据解析失败', String(e));
      }
    }
    setIsLoading(false);
  }, []);

  // 全局监听登录态失效事件（任何 401 都会触发）
  useEffect(() => {
    const handleExpired = (e: Event) => {
      const customEvent = e as CustomEvent<{ reason: string }>;
      const reason = customEvent.detail?.reason || '登录状态已失效，请重新登录';
      logger.info('[auth] 收到登录态失效事件:', reason);
      // 清 React state（清存储已在 api.ts 的 triggerAuthExpired 里做了）
      setToken(null);
      setUser(null);
      // 用 toast 通知用户（动态 import 避免循环依赖）
      import('sonner').then(({ toast }) => {
        toast.error(reason, { id: 'auth-expired-toast' });
      });
    };
    window.addEventListener(AUTH_EXPIRED_EVENT, handleExpired);
    return () => window.removeEventListener(AUTH_EXPIRED_EVENT, handleExpired);
  }, []);

  const login = useCallback(async (username: string, password: string) => {
    let tokenVal: string;
    let userVal: AuthUser;
    let isNewDevice = false;
    let apiFailed = false;

    try {
      const res = await api.post('/auth/login', { username, password });
      const data = res.data as any;
      if (!data.success) {
        throw new Error(data.error || '登录失败');
      }
      tokenVal = data.token;
      // 兼容两种返回格式：data.user 对象 或 只有 username 字段
      if (data.user && typeof data.user === 'object') {
        userVal = data.user as AuthUser;
      } else {
        userVal = {
          id: data.userId ?? 1,
          username: data.username ?? username,
          nickname: data.nickname ?? data.username ?? username,
          role: data.role || 'user',
        };
      }
      // 后端若返回 role（super_admin / user 等），直接信任后端
      isNewDevice = !!data.isNewDevice;
    } catch (err: any) {
      const status = err?.response?.status;
      // 明确的业务错误码：直接抛出，不降级
      if (status === 401) {
        throw new Error('密码错误，请重试');
      }
      if (status === 404) {
        throw new Error('账号不存在，请先注册');
      }
      if (status === 403) {
        throw new Error('账号已被禁用，请联系管理员');
      }
      // 网络或其他错误：降级到本地验证模式
      apiFailed = true;
      logger.warn('登录接口调用失败，降级到本地验证模式', String(err));
      const localAcc = verifyLocalAccount(username, password);
      if (!localAcc) {
        const accStatus = getAccountStatus(username);
        if (accStatus === 'pending') {
          throw new Error('账号待审批中，请联系管理员通过后再登录');
        }
        if (accStatus === 'rejected') {
          throw new Error('账号注册申请未通过，请联系管理员');
        }
        throw new Error('用户名或密码错误');
      }
      tokenVal = `local_${username}_${Date.now()}`;
      userVal = {
        id: localAcc.id || 0,
        username: localAcc.username,
        nickname: localAcc.nickname,
        role: localAcc.role,
      };
      isNewDevice = true;
    }

    // 本地降级模式 / 后端没返回 role 时，wuxin209 白名单兜底
    if (username === 'wuxin209' && (apiFailed || userVal.role === 'user')) {
      userVal = { ...userVal, role: 'super_admin' };
    }

    // 同步到账号列表：登录成功后更新最后登录时间；若账号不存在则补一条注册记录
    const now = new Date().toISOString();
    const existing = _readAccounts().find(a => a.username === username);
    if (existing) {
      touchAccountLogin(username);
      // 如果本地记录有 role，优先用本地 role（如 super_admin 白名单已生效）
      if (existing.role && userVal.role === 'user') {
        userVal = { ...userVal, role: existing.role };
      }
    } else {
      upsertAccount({
        id: userVal.id || Date.now(),
        username: userVal.username,
        nickname: userVal.nickname,
        role: userVal.role,
        password: password,
        register_at: now,
        last_login_at: now,
        status: 'active',
      });
    }

    // 确保 wuxin209 在账号列表中标记为主账号
    if (username === 'wuxin209') {
      const all = _readAccounts();
      const i = all.findIndex(a => a.username === 'wuxin209');
      if (i >= 0) {
        all[i].role = 'super_admin';
        all[i].status = 'active';
        _writeAccounts(all);
      }
    }

    setToken(tokenVal);
    setUser(userVal);
    scopedStorage.setItem(TOKEN_KEY, tokenVal);
    scopedStorage.setItem(USER_KEY, JSON.stringify(userVal));
    // 保存新设备标记（供安全弹窗使用）
    if (isNewDevice) {
      scopedStorage.setItem('last_login_reason', '新设备登录');
    } else {
      scopedStorage.removeItem('last_login_reason');
    }
  }, []);

  const register = useCallback(async (username: string, password: string, nickname?: string) => {
    const now = new Date().toISOString();
    let registered = false;
    let userVal: AuthUser | null = null;
    let apiFailed = false;
    let autoLoggedIn = false;

    try {
      const res = await api.post('/auth/register', { username, password, nickname });
      const data = res.data as any;
      if (!data.success) {
        throw new Error(data.error || '注册失败');
      }
      registered = true;
      // 接口返回 token + user → 自动登录；若接口返回 status=pending → 不自动登录
      if (data.token && data.username && data.status !== 'pending') {
        userVal = {
          id: data.userId ?? 0,
          username: data.username,
          nickname: data.nickname ?? data.username ?? username,
          role: data.role || 'user',
        };
        if (username === 'wuxin209' && userVal.role === 'user') {
          userVal.role = 'super_admin';
        }
        setToken(data.token);
        setUser(userVal);
        scopedStorage.setItem(TOKEN_KEY, data.token);
        scopedStorage.setItem(USER_KEY, JSON.stringify(userVal));
        autoLoggedIn = true;
      }
    } catch (err: any) {
      const status = err?.response?.status;
      if (status === 409) {
        throw new Error('该用户名已被注册，请换一个');
      }
      apiFailed = true;
      logger.warn('注册接口调用失败，降级到本地验证模式', String(err));
      const existing = _readAccounts().find(a => a.username === username);
      if (existing) {
        throw new Error('该用户名已被注册，请换一个');
      }
    }

    // 写入账号列表（无论接口还是降级模式，注册成功都记录）
    // 新注册用户默认进入待审批状态（super_admin 白名单除外）
    if (registered || apiFailed) {
      const isSuper = username === 'wuxin209';
      const role: AuthAccountRecord['role'] = isSuper ? 'super_admin' : 'user';
      const status: AuthAccountRecord['status'] = isSuper ? 'active' : 'pending';
      upsertAccount({
        id: userVal?.id ?? Date.now(),
        username,
        nickname: nickname || username,
        role,
        password,
        register_at: now,
        last_login_at: '',
        status,
      });
    }

    // 只有接口返回了 token 且非 pending 才已登录；其他情况不自动登录
    if (!userVal && (registered || apiFailed)) {
      // 非自动登录：pending 状态提示等待审批
      autoLoggedIn = false;
    }

    return { autoLoggedIn };
  }, []);

  const logout = useCallback(async () => {
    if (token) {
      try {
        await api.post('/auth/logout');
      } catch (e) {
        logger.warn('登出请求失败', String(e));
      }
    }
    setToken(null);
    setUser(null);
    clearAuthStorage();
  }, [token]);

  const refreshUser = useCallback(async () => {
    if (!token) return;
    try {
      const res = await api.get('/auth/me');
      const data = res.data as any;
      if (data.user) {
        setUser(data.user);
        scopedStorage.setItem(USER_KEY, JSON.stringify(data.user));
      }
    } catch (e) {
      logger.warn('刷新用户信息失败', String(e));
    }
  }, [token]);

  const approveAccount = useCallback(async (username: string, adminUsername?: string): Promise<{ success: boolean; error?: string }> => {
    try {
      // 真实后端接口：POST /api/auth/accounts，body 带 action=approve/reject/delete
      const res = await api.post('/auth/accounts', {
        username,
        action: 'approve',
      });
      const data = res.data as any;
      if (data && data.success === false) {
        return { success: false, error: data.error || '审批失败' };
      }
      // 本地同步：pending → active
      const all = _readAccounts();
      const idx = all.findIndex(a => a.username === username);
      if (idx >= 0) {
        all[idx].status = 'active';
        _writeAccounts(all);
      }
      return { success: true };
    } catch (e: any) {
      const msg = e?.response?.data?.error || e?.message || '审批失败';
      logger.error('[auth] 审批失败', msg);
      // 接口失败不降级到本地 —— 保持真实状态
      return { success: false, error: msg };
    }
  }, []);

  const rejectAccount = useCallback(async (username: string, adminUsername?: string): Promise<{ success: boolean; error?: string }> => {
    try {
      // 真实后端接口：POST /api/auth/accounts，action=reject 时后端删除/禁用该账号
      const res = await api.post('/auth/accounts', {
        username,
        action: 'reject',
      });
      const data = res.data as any;
      if (data && data.success === false) {
        return { success: false, error: data.error || '操作失败' };
      }
      // 本地同步：→ rejected（本地保留记录便于查看，后端已删除/禁用）
      const all = _readAccounts();
      const idx = all.findIndex(a => a.username === username);
      if (idx >= 0) {
        all[idx].status = 'rejected';
        _writeAccounts(all);
      }
      return { success: true };
    } catch (e: any) {
      const msg = e?.response?.data?.error || e?.message || '操作失败';
      logger.error('[auth] 拒绝失败', msg);
      return { success: false, error: msg };
    }
  }, []);

  const updateAccountPassword = useCallback(async (accountId: number, newPassword: string): Promise<boolean | 'local'> => {
    let apiSuccess = false;
    try {
      try {
        // 调用后端真实重置接口：/auth/sub-accounts/:id/reset-password
        // 后端用 better-sqlite3 持久化到 users.password_hash（bcrypt 哈希），同时清 active_sessions
        const res = await api.post(`/auth/sub-accounts/${accountId}/reset-password`, {
          password: newPassword,
        });
        const data = res.data as any;
        if (data && data.success === false) {
          throw new Error(data.error || '修改失败');
        }
        apiSuccess = true;
      } catch (e) {
        logger.warn('[auth] 服务端改密失败，降级到本地', String(e));
      }
      // 本地 scopedStorage 同步（保持降级登录可用）
      const all = _readAccounts();
      const idx = all.findIndex(a => a.id === accountId);
      if (idx >= 0) {
        all[idx].password = newPassword;
        _writeAccounts(all);
      }
      return apiSuccess ? true : 'local';
    } catch (e) {
      logger.error('[auth] 修改密码失败', String(e));
      return false;
    }
  }, []);

  return (
    <AuthContext.Provider value={{
      user,
      token,
      isLoggedIn: !!user && !!token,
      isLoading,
      login,
      register,
      logout,
      refreshUser,
      approveAccount,
      rejectAccount,
      updateAccountPassword,
    }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) {
    throw new Error('useAuth 必须在 AuthProvider 内使用');
  }
  return ctx;
}
