import axios from 'axios';
import { scopedStorage, getAppId } from '@lark-apaas/client-toolkit-lite';

// 登录态失效事件名（401 时 api.ts → React 层通信的桥梁）
export const AUTH_EXPIRED_EVENT = 'auth:expired';

// 需要清除的所有 auth 相关 key（本地降级账号列表也清，保持一致）
const AUTH_STORAGE_KEYS = [
  'auth_token',
  'auth_user',
  'xinzhihai_accounts',
  'auth_last_sync',
  'auth_device_id',
];

/**
 * 全局清理登录态：401 / 主动登出 / token 失效时统一调用
 * 确保所有 auth_ 开头的 key 都被清除，不留任何残留
 */
export function clearAuthStorage() {
  for (const key of AUTH_STORAGE_KEYS) {
    try { scopedStorage.removeItem(key); } catch { /* ignore */ }
  }
  // 兜底：扫一遍 scopedStorage 里所有 auth 开头的 key 都清掉
  try {
    const keys = Object.keys(localStorage);
    for (const k of keys) {
      if (k.includes('auth_') || k.includes('xinzhihai_')) {
        try { scopedStorage.removeItem(k); } catch { /* ignore */ }
      }
    }
  } catch { /* ignore */ }
}

/**
 * 触发登录态失效：清存储 + 发自定义事件 + 跳登录
 * 注意：不在拦截器里直接 toast（避免循环依赖 useAuth），
 * 由 AuthProvider 监听事件后统一处理 UI 反馈。
 */
export function triggerAuthExpired(reason?: string) {
  clearAuthStorage();
  // 通知 React 层更新 state + 弹提示
  window.dispatchEvent(new CustomEvent(AUTH_EXPIRED_EVENT, {
    detail: { reason: reason || '登录状态已失效，请重新登录' },
  }));
}

// 自定义 axios 实例：专门用于 auth / places 等后端 API
// - 开发环境：后端 3001 端口，前端 8001 端口，需指定完整 baseURL
// - 生产环境：同源同域，直接走相对路径
const isLocalDev = typeof window !== 'undefined' && window.location.port === '8001';

const api = axios.create({
  baseURL: isLocalDev ? 'http://localhost:3001/api' : '/api',
  withCredentials: true,
});

// 请求拦截：自动附加 token
api.interceptors.request.use((config) => {
  const token = scopedStorage.getItem('auth_token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

// 响应拦截：401 立即清理登录态并通知上层强制登出
api.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response?.status === 401) {
      // 只对非登录接口触发全局失效（登录接口自己的 401 属于正常业务错误）
      const url = error.config?.url || '';
      const isAuthEndpoint = url.includes('/auth/login') || url.includes('/auth/register');
      if (!isAuthEndpoint) {
        const reason = error.response?.data?.error || '登录状态已失效，请重新登录';
        triggerAuthExpired(reason);
      }
    }
    return Promise.reject(error);
  }
);

export default api;

// appId 兜底，防止 tree-shake 误删（getAppId 在 lite 里可能懒加载）
export function safeGetAppId(): string | undefined {
  try {
    return getAppId();
  } catch {
    return undefined;
  }
}
