import { useState } from 'react';
import { resolveAppUrl } from '@lark-apaas/client-toolkit-lite';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Loader2, Sparkles, BookOpen } from 'lucide-react';
import { useAuth } from '@/hooks/useAuth';
import { toast } from 'sonner';
import type { ThemeConfig, FestivalBadge } from '@/lib/theme';
import { Image } from '@/components/ui/image';

interface LoginPageProps {
  theme: ThemeConfig;
  festival: FestivalBadge;
}

export default function LoginPage({ theme, festival }: LoginPageProps) {
  const { login, register } = useAuth();
  const [isSubmitting, setIsSubmitting] = useState(false);

  // 登录表单
  const [loginUsername, setLoginUsername] = useState('');
  const [loginPassword, setLoginPassword] = useState('');

  // 注册表单
  const [regUsername, setRegUsername] = useState('');
  const [regPassword, setRegPassword] = useState('');
  const [regNickname, setRegNickname] = useState('');

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!loginUsername || !loginPassword) {
      toast.error('请输入用户名和密码');
      return;
    }
    setIsSubmitting(true);
    try {
      await login(loginUsername, loginPassword);
      toast.success('登录成功，欢迎回来');
    } catch (err: any) {
      toast.error(err.message || '登录失败');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!regUsername || !regPassword) {
      toast.error('请输入用户名和密码');
      return;
    }
    setIsSubmitting(true);
    try {
      const result = await register(regUsername, regPassword, regNickname || undefined);
      if (result.autoLoggedIn) {
        toast.success('注册成功，已自动登录');
      } else {
        toast.success('注册申请已提交，请等待管理员审批通过后登录');
        // 切回登录 tab
        const tabsList = document.querySelector('[data-state="active"][data-orientation="horizontal"]');
        // 简单切换：直接设置第一个 tab 为 active（通过原生 event 不可行，用 state 切换）
        // 这里走 DOM 方式找到 login tab 并点击
        const loginTab = document.querySelector('[data-value="login"]') as HTMLElement | null;
        if (loginTab) loginTab.click();
      }
    } catch (err: any) {
      toast.error(err.message || '注册失败');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div
      className={`min-h-screen w-full flex items-center justify-center px-4 bg-gradient-to-br ${theme.bgGradient}`}
      style={{
        '--theme-primary': theme.primary,
        '--theme-primary-light': theme.primaryLight,
      } as React.CSSProperties}
    >
      {/* 节日装饰 */}
      {festival.active && festival.icon && (
        <div className="absolute top-6 left-1/2 -translate-x-1/2 text-2xl">
          {festival.icon}
        </div>
      )}

      <div
        className="w-full max-w-md rounded-2xl p-8 relative overflow-hidden"
        style={{
          backgroundColor: theme.ui.glassBg,
          backdropFilter: 'blur(20px) saturate(180%)',
          WebkitBackdropFilter: 'blur(20px) saturate(180%)',
          border: `1px solid ${theme.ui.glassBorder || theme.ui.cardBorder}`,
          boxShadow: theme.ui.glassShadow,
        }}
      >
        {/* Logo & 标题 */}
        <div className="flex flex-col items-center gap-3 mb-6">
          <div
            className="size-14 rounded-xl flex items-center justify-center"
            style={{ backgroundColor: theme.primary }}
          >
            <BookOpen className="size-7 text-white" />
          </div>
          <div className="text-center">
            <h1 className="text-xl font-bold" style={{ color: theme.primaryDark }}>
              鑫之海运营手册
            </h1>
            <p className="text-xs text-muted-foreground mt-1">
              跨境运营 · 每日计划 · 效率工具
            </p>
          </div>
        </div>

        {/* 登录/注册 Tabs */}
        <Tabs defaultValue="login" className="w-full">
          <TabsList className="w-full grid grid-cols-2 mb-4 h-10">
            <TabsTrigger value="login">登录</TabsTrigger>
            <TabsTrigger value="register">注册</TabsTrigger>
          </TabsList>

          <TabsContent value="login">
            <form onSubmit={handleLogin} className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="login-username">用户名</Label>
                <Input
                  id="login-username"
                  type="text"
                  value={loginUsername}
                  onChange={(e) => setLoginUsername(e.target.value)}
                  placeholder="请输入用户名"
                  autoComplete="username"
                  style={{ borderColor: theme.ui.cardBorder }}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="login-password">密码</Label>
                <Input
                  id="login-password"
                  type="password"
                  value={loginPassword}
                  onChange={(e) => setLoginPassword(e.target.value)}
                  placeholder="请输入密码"
                  autoComplete="current-password"
                  style={{ borderColor: theme.ui.cardBorder }}
                />
              </div>
              <Button
                type="submit"
                className="w-full h-11"
                style={{ backgroundColor: theme.primary }}
                disabled={isSubmitting}
              >
                {isSubmitting ? (
                  <Loader2 className="size-4 mr-2 animate-spin" />
                ) : (
                  <Sparkles className="size-4 mr-2" />
                )}
                {isSubmitting ? '登录中...' : '登录'}
              </Button>
              <p className="text-xs text-muted-foreground text-center">
                登录后可使用全部功能，数据本地加密存储
              </p>
            </form>
          </TabsContent>

          <TabsContent value="register">
            <form onSubmit={handleRegister} className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="reg-username">用户名</Label>
                <Input
                  id="reg-username"
                  type="text"
                  value={regUsername}
                  onChange={(e) => setRegUsername(e.target.value)}
                  placeholder="设置用户名"
                  autoComplete="username"
                  style={{ borderColor: theme.ui.cardBorder }}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="reg-nickname">昵称（可选）</Label>
                <Input
                  id="reg-nickname"
                  type="text"
                  value={regNickname}
                  onChange={(e) => setRegNickname(e.target.value)}
                  placeholder="显示的昵称"
                  autoComplete="nickname"
                  style={{ borderColor: theme.ui.cardBorder }}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="reg-password">密码</Label>
                <Input
                  id="reg-password"
                  type="password"
                  value={regPassword}
                  onChange={(e) => setRegPassword(e.target.value)}
                  placeholder="设置密码"
                  autoComplete="new-password"
                  style={{ borderColor: theme.ui.cardBorder }}
                />
              </div>
              <Button
                type="submit"
                className="w-full h-11"
                style={{ backgroundColor: theme.primary }}
                disabled={isSubmitting}
              >
                {isSubmitting ? (
                  <Loader2 className="size-4 mr-2 animate-spin" />
                ) : (
                  <Sparkles className="size-4 mr-2" />
                )}
                {isSubmitting ? '注册中...' : '注册账号'}
              </Button>
              <p className="text-xs text-muted-foreground text-center">
                注册即表示同意用户协议，账号数据本地保存
              </p>
            </form>
          </TabsContent>
        </Tabs>

        {/* 底部 Logo */}
        <div className="mt-6 pt-4 border-t text-center" style={{ borderColor: theme.ui.dividerLine }}>
          <div className="flex items-center justify-center gap-2">
            <Image
              src={resolveAppUrl('/assets/logo-256.png')}
              alt="鑫之海"
              className="size-5 object-contain"
            />
            <span className="text-xs text-muted-foreground">
              鑫之海 · 让跨境运营更简单
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}
