import { lazy, Suspense, type ComponentType } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { Layout } from '@/components/Layout';
import NotFoundPage from '@/pages/NotFoundPage/NotFoundPage';
import DailyPlanPage from '@/pages/DailyPlanPage/DailyPlanPage';

const MarketAnalysisPage = lazy(() => import('@/pages/MarketAnalysisPage/MarketAnalysisPage'));
const ProfitCalculatorPage = lazy(() => import('@/pages/ProfitCalculatorPage/ProfitCalculatorPage'));
const PeakSeasonPage = lazy(() => import('@/pages/PeakSeasonPage/PeakSeasonPage'));
const LanguageLearningPage = lazy(() => import('@/pages/LanguageLearningPage/LanguageLearningPage'));
const OperationTipsPage = lazy(() => import('@/pages/OperationTipsPage/OperationTipsPage'));
const RecipePage = lazy(() => import('@/pages/RecipePage/RecipePage'));
const ViralShortsPage = lazy(() => import('@/pages/ViralShortsPage/ViralShortsPage'));
const AILearningPage = lazy(() => import('@/pages/AILearningPage/AILearningPage'));
const NewsPage = lazy(() => import('@/pages/NewsPage/NewsPage'));
const MarketMorningPage = lazy(() => import('@/pages/MarketMorningPage/MarketMorningPage'));
const WeatherPage = lazy(() => import('@/pages/WeatherPage/WeatherPage'));
const TeamManagementPage = lazy(() => import('@/pages/TeamManagementPage/TeamManagementPage'));
const PurchaseOrderPage = lazy(() => import('@/pages/PurchaseOrderPage/PurchaseOrderPage'));

function PageFallback() {
  return (
    <div className="py-12 flex flex-col items-center justify-center">
      <div className="size-8 rounded-full border-2 border-primary border-t-transparent animate-spin mb-3" />
      <p className="text-sm text-muted-foreground">加载中...</p>
    </div>
  );
}

function withLazy(Comp: ComponentType) {
  return (
    <Suspense fallback={<PageFallback />}>
      <Comp />
    </Suspense>
  );
}

export default function App() {
  return (
    <Routes>
      <Route element={<Layout />}>
        <Route index element={<DailyPlanPage />} />
        <Route path="market" element={withLazy(MarketAnalysisPage)} />
        <Route path="profit" element={withLazy(ProfitCalculatorPage)} />
        <Route path="peak" element={withLazy(PeakSeasonPage)} />
        <Route path="language" element={withLazy(LanguageLearningPage)} />
        <Route path="operation" element={withLazy(OperationTipsPage)} />
        <Route path="recipe" element={withLazy(RecipePage)} />
        <Route path="viral" element={withLazy(ViralShortsPage)} />
        <Route path="ai" element={withLazy(AILearningPage)} />
        <Route path="news" element={withLazy(NewsPage)} />
        <Route path="morning" element={withLazy(MarketMorningPage)} />
        <Route path="weather" element={withLazy(WeatherPage)} />
        <Route path="team" element={withLazy(TeamManagementPage)} />
        <Route path="purchase" element={withLazy(PurchaseOrderPage)} />
        {/* 旧 KPI 路由：重定向到首页（KPI 已并入每日巡店） */}
        <Route path="kpi" element={<Navigate to="/" replace />} />
      </Route>
      <Route path="*" element={<NotFoundPage />} />
    </Routes>
  );
}
