import { useState } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs';
import {
  User,
  LogOut,
  Loader2,
  Users,
  CheckCircle2,
  Cloud,
  CloudOff,
  ChevronDown,
} from 'lucide-react';
import { useAuth } from '@/hooks/useAuth';
import { toast } from 'sonner';
import type { ThemeConfig } from '@/lib/theme';
import type { SyncStatus } from '@/hooks/useDataSync';

interface AuthDialogProps {
  theme: ThemeConfig;
  syncStatus?: SyncStatus;
  onOpenTeamPanel?: () => void;
  trigger?: React.ReactNode;
}

export default function AuthDialog({ theme, syncStatus = 'idle', onOpenTeamPanel, trigger }: AuthDialogProps) {
  const { user, isLoggedIn, login, register, logout } = useAuth();
  const [open, setOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // 登录表单
  const [loginUsername, setLoginUsername] = useState('');
  const [loginPassword, setLoginPassword] = useState('');

  // 注册表单
  const [regUsername, setRegUsername] = useState('');
  const [regPassword, setRegPassword] = useState('');
  const [regNickname, setRegNickname] = useState('');

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!loginUsername || !loginPassword) {
      toast.error('请输入用户名和密码');
      return;
    }
    setIsSubmitting(true);
    try {
      await login(loginUsername, loginPassword);
      toast.success('登录成功');
      setOpen(false);
      setLoginUsername('');
      setLoginPassword('');
    } catch (err: any) {
      toast.error(err.message || '登录失败');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!regUsername || !regPassword) {
      toast.error('请输入用户名和密码');
      return;
    }
    setIsSubmitting(true);
    try {
      await register(regUsername, regPassword, regNickname || undefined);
      toast.success('注册成功，已自动登录');
      setOpen(false);
      setRegUsername('');
      setRegPassword('');
      setRegNickname('');
    } catch (err: any) {
      toast.error(err.message || '注册失败');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleLogout = async () => {
    await logout();
    toast.success('已退出登录');
  };

  const syncLabel = {
    idle: '已同步',
    syncing: '同步中',
    synced: '已同步',
    error: '同步失败',
  }[syncStatus];

  const syncColor = {
    idle: theme.primary,
    syncing: theme.primaryLight,
    synced: theme.primary,
    error: theme.priority.p0,
  }[syncStatus];

  // 已登录：头像下拉菜单
  if (isLoggedIn && user) {
    const isSuperAdmin = user.role === 'super_admin' || user.role === 'admin';
    const initial = (user.nickname || user.username).charAt(0).toUpperCase();

    return (
      <div className="flex items-center gap-2">
        {/* 同步状态指示 */}
        {isLoggedIn && (
          <div className="hidden lg:flex items-center gap-1 text-xs" style={{ color: syncColor }}>
            {syncStatus === 'syncing' ? (
              <Loader2 className="size-3 animate-spin" />
            ) : syncStatus === 'error' ? (
              <CloudOff className="size-3" />
            ) : (
              <Cloud className="size-3" />
            )}
            <span>{syncLabel}</span>
          </div>
        )}

        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button
              variant="ghost"
              size="sm"
              className="h-8 px-1.5 gap-2 pl-1.5"
            >
              <div
                className="size-6 rounded-full flex items-center justify-center text-xs font-bold text-white shrink-0"
                style={{ backgroundColor: theme.primary }}
              >
                {initial}
              </div>
              <span className="text-xs font-medium hidden sm:inline max-w-[80px] truncate">
                {user.nickname || user.username}
              </span>
              <ChevronDown className="size-3 text-muted-foreground hidden sm:inline" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent
            align="end"
            className="w-52"
            style={{
              backgroundColor: theme.ui.glassBg,
              backdropFilter: 'blur(16px) saturate(180%)',
              WebkitBackdropFilter: 'blur(16px) saturate(180%)',
              borderColor: theme.ui.cardBorder,
            }}
          >
            <DropdownMenuLabel>
              <div className="flex items-center gap-2">
                <div
                  className="size-8 rounded-full flex items-center justify-center text-xs font-bold text-white"
                  style={{ backgroundColor: theme.primary }}
                >
                  {initial}
                </div>
                <div className="min-w-0">
                  <div className="text-sm font-semibold truncate">{user.nickname || user.username}</div>
                  <div className="text-[10px] text-muted-foreground truncate">@{user.username}</div>
                </div>
              </div>
            </DropdownMenuLabel>
            <DropdownMenuSeparator />
            <DropdownMenuItem
              className="text-xs flex items-center gap-2 cursor-default"
              style={{ color: syncColor }}
            >
              {syncStatus === 'syncing' ? (
                <Loader2 className="size-3.5 animate-spin" />
              ) : syncStatus === 'error' ? (
                <CloudOff className="size-3.5" />
              ) : (
                <CheckCircle2 className="size-3.5" />
              )}
              个人数据：{syncLabel}
            </DropdownMenuItem>
            {isSuperAdmin && (
              <>
                <DropdownMenuSeparator />
                <DropdownMenuItem
                  className="text-xs gap-2 cursor-pointer"
                  onClick={() => {
                    onOpenTeamPanel?.();
                  }}
                >
                  <Users className="size-3.5" style={{ color: theme.primary }} />
                  <span>团队管理</span>
                </DropdownMenuItem>
              </>
            )}
            <DropdownMenuSeparator />
            <DropdownMenuItem
              className="text-xs gap-2 cursor-pointer text-destructive"
              onClick={handleLogout}
            >
              <LogOut className="size-3.5" />
              退出登录
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    );
  }

  // 未登录：登录按钮 + 弹窗
  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        {trigger || (
          <Button
            variant="ghost"
            size="sm"
            className="h-7 px-2 text-xs gap-1"
          >
            <User className="size-3.5" />
            登录
          </Button>
        )}
      </DialogTrigger>
      <DialogContent
        className="sm:max-w-md"
        style={{
          backgroundColor: theme.ui.glassBg,
          backdropFilter: 'blur(20px) saturate(180%)',
          WebkitBackdropFilter: 'blur(20px) saturate(180%)',
          borderColor: theme.ui.cardBorder,
        }}
      >
        <DialogHeader>
          <DialogTitle style={{ color: theme.primaryDark }}>
            鑫之海运营手册账号
          </DialogTitle>
        </DialogHeader>

        <Tabs defaultValue="login" className="w-full">
          <TabsList className="w-full mb-4">
            <TabsTrigger value="login" className="flex-1">登录</TabsTrigger>
            <TabsTrigger value="register" className="flex-1">注册</TabsTrigger>
          </TabsList>

          <TabsContent value="login">
            <form onSubmit={handleLogin} className="space-y-4">
              <div className="space-y-2">
                <Label>用户名</Label>
                <Input
                  value={loginUsername}
                  onChange={(e) => setLoginUsername(e.target.value)}
                  placeholder="请输入用户名"
                  autoComplete="username"
                />
              </div>
              <div className="space-y-2">
                <Label>密码</Label>
                <Input
                  type="password"
                  value={loginPassword}
                  onChange={(e) => setLoginPassword(e.target.value)}
                  placeholder="请输入密码"
                  autoComplete="current-password"
                />
              </div>
              <Button
                type="submit"
                className="w-full"
                disabled={isSubmitting}
                style={{ backgroundColor: theme.primary }}
              >
                {isSubmitting && <Loader2 className="size-4 mr-2 animate-spin" />}
                登录
              </Button>
              <p className="text-xs text-center text-muted-foreground">
                未注册账号将自动以游客模式使用，数据存储在本地
              </p>
            </form>
          </TabsContent>

          <TabsContent value="register">
            <form onSubmit={handleRegister} className="space-y-4">
              <div className="space-y-2">
                <Label>用户名</Label>
                <Input
                  value={regUsername}
                  onChange={(e) => setRegUsername(e.target.value)}
                  placeholder="请设置用户名"
                  autoComplete="username"
                />
              </div>
              <div className="space-y-2">
                <Label>昵称（可选）</Label>
                <Input
                  value={regNickname}
                  onChange={(e) => setRegNickname(e.target.value)}
                  placeholder="显示名称"
                />
              </div>
              <div className="space-y-2">
                <Label>密码</Label>
                <Input
                  type="password"
                  value={regPassword}
                  onChange={(e) => setRegPassword(e.target.value)}
                  placeholder="至少6位"
                  autoComplete="new-password"
                />
              </div>
              <Button
                type="submit"
                className="w-full"
                disabled={isSubmitting}
                style={{ backgroundColor: theme.primary }}
              >
                {isSubmitting && <Loader2 className="size-4 mr-2 animate-spin" />}
                注册并登录
              </Button>
            </form>
          </TabsContent>
        </Tabs>
      </DialogContent>
    </Dialog>
  );
}
