import { useState, useEffect, useRef } from 'react';
import { ErrorBoundary } from 'react-error-boundary';
import { resolveAppUrl, logger } from '@lark-apaas/client-toolkit-lite';
import { Outlet, useLocation, useNavigate } from 'react-router-dom';
import { Menu, BookOpen, Clock } from 'lucide-react';
import AppSidebar from '@/components/AppSidebar';
import BottomNav from '@/components/BottomNav';
import ShipmentAlertBanner from '@/components/ShipmentAlertBanner';
import { useShipmentAlert } from '@/hooks/useShipmentAlert';
import AuthDialog from '@/components/AuthDialog';
import NewDeviceAlert from '@/components/NewDeviceAlert';
import LoginPage from '@/components/LoginPage';
import { useSeasonalTheme } from '@/hooks/useSeasonalTheme';
import { useAuth } from '@/hooks/useAuth';
import { useDataSync } from '@/hooks/useDataSync';
import { Image } from '@/components/ui/image';

// 路径→模块名称映射（顶部信息栏展示）
const MODULE_NAMES: Record<string, string> = {
  '': '每日计划工作台',
  'market': '市场分析',
  'profit': '利润测算',
    'peak': '旺季备战',
  'operation': '运营技巧',
  'viral': '爆款二创',
  'ai': 'AI技巧本',
  'news': '新闻资讯',
  'morning': '市场早讯',
  'weather': '天气预示',
  'language': '外语学习',
  'recipe': '菜谱推荐',
};

export const Layout = () => {
  const { theme, festival, themeOverride, setThemeOverride, now } = useSeasonalTheme();
  const { isLoggedIn, user, isLoading } = useAuth();
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const topbarRef = useRef<HTMLDivElement>(null);
  const location = useLocation();
  const navigate = useNavigate();

  // 顶部信息栏滚动增强：往下滚时毛玻璃加深 + 淡投影
  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 4);
    };
    // main 是滚动容器，监听它的滚动
    const mainEl = document.querySelector('main');
    if (mainEl) {
      mainEl.addEventListener('scroll', handleScroll);
      return () => mainEl.removeEventListener('scroll', handleScroll);
    }
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // 数据云同步
  const { syncStatus, isNewDevice, dismissNewDevice } = useDataSync();

  // 运输超7天异常提醒
  const { counts, bannerVisible, markAsRead } = useShipmentAlert();

  // 主题切换时同步到云端
  useEffect(() => {
    if (!isLoggedIn) return;
    // 主题变更由 useSeasonalTheme 负责存储，这里仅在登录态下确保云端同步
    // （初次同步时会合并上传主题偏好）
  }, [isLoggedIn, themeOverride]);

  // 取当前模块名
  const pathKey = location.pathname.split('/')[1] || '';
  const moduleName = MODULE_NAMES[pathKey] || '每日计划工作台';

  // 顶部信息栏更新日期
  const updateDate = `${now.getFullYear()}.${String(now.getMonth() + 1).padStart(2, '0')}.${String(now.getDate()).padStart(2, '0')}`;

  // 未登录：显示全屏登录页
  if (!isLoggedIn && !isLoading) {
    return <LoginPage theme={theme} festival={festival} />;
  }

  // 加载中：显示简单 loading
  if (isLoading) {
    return (
      <div
        className={`min-h-screen w-full flex items-center justify-center bg-gradient-to-br ${theme.bgGradient}`}
      >
        <div className="flex flex-col items-center gap-3">
          <div
            className="size-12 rounded-xl flex items-center justify-center animate-pulse"
            style={{ backgroundColor: theme.primary }}
          >
            <BookOpen className="size-6 text-white" />
          </div>
          <p className="text-sm text-muted-foreground">加载中...</p>
        </div>
      </div>
    );
  }

  return (
    <div
      className={`min-h-screen bg-gradient-to-br ${theme.bgGradient} flex relative`}
      style={{
        '--theme-primary': theme.primary,
        '--theme-primary-light': theme.primaryLight,
        '--theme-primary-dark': theme.primaryDark,
      } as React.CSSProperties}
    >
      {/* 背景微光层 —— 两团极低透明度主色径向渐变光斑 */}
      <div className="bg-ambient-light" aria-hidden="true" />

      <AppSidebar
        theme={theme}
        festival={festival}
        isOpen={sidebarOpen}
        onClose={() => setSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col min-w-0">
        {/* Mobile Top Bar */}
        <header
          ref={topbarRef}
          className={`sticky top-0 z-30 md:hidden border-b px-4 py-2.5 flex items-center gap-3 theme-transition ${scrolled ? 'topbar-scrolled' : ''}`}
          style={{
            backgroundColor: theme.ui.topbarBg,
            borderColor: scrolled ? `${theme.primary}20` : theme.ui.dividerLine,
            backdropFilter: 'blur(12px) saturate(180%)',
            WebkitBackdropFilter: 'blur(12px) saturate(180%)',
          }}
        >
          <button
            onClick={() => setSidebarOpen(true)}
            className="p-2 -ml-2 rounded-lg hover:bg-accent transition-colors"
            aria-label="打开菜单"
          >
            <Menu className="size-5" style={{ color: theme.primary }} />
          </button>
          <div className="flex-1 flex items-center gap-2 justify-center">
            <Image
              src={resolveAppUrl('/assets/logo-256.png')}
              alt="鑫之海"
              className="size-6 object-contain"
            />
            <span className="font-semibold" style={{ color: theme.primary }}>
              鑫之海
            </span>
          </div>
          <div className="w-9">
            <div className="md:hidden">
              <AuthDialog
                theme={theme}
                syncStatus={syncStatus}
                onOpenTeamPanel={() => navigate('/team')}
              />
            </div>
          </div>
        </header>

        {/* 顶部固定信息栏 —— 桌面端磨砂玻璃质感 */}
        <div
          className={`hidden md:flex sticky top-0 z-30 items-center justify-between px-6 py-2 text-[12px] border-b theme-transition ${scrolled ? 'topbar-scrolled' : ''}`}
          style={{
            backgroundColor: theme.ui.topbarBg,
            borderColor: scrolled ? `${theme.primary}18` : theme.ui.dividerLine,
            backdropFilter: 'blur(12px) saturate(180%)',
            WebkitBackdropFilter: 'blur(12px) saturate(180%)',
          }}
        >
          <div className="flex items-center gap-3">
            <div className="flex items-center gap-1.5" style={{ color: theme.primaryDark }}
            >
              <BookOpen className="size-3.5" />
              <span className="font-semibold">鑫之海运营手册</span>
              <span className="font-normal opacity-50">v3.0</span>
            </div>
            <div
              className="h-3 w-px"
              style={{ backgroundColor: theme.ui.dividerLine }}
            />
            <div className="flex items-center gap-1.5" style={{ color: theme.primaryDark + '99' }}>
              <span className="opacity-60">当前模块：</span>
              <span className="font-medium" style={{ color: theme.primary }}>
                {moduleName}
              </span>
            </div>
          </div>
          <div className="flex items-center gap-3" style={{ color: theme.primaryDark + '80' }}>
            <div className="hidden md:block">
              <AuthDialog
                theme={theme}
                syncStatus={syncStatus}
                onOpenTeamPanel={() => navigate('/team')}
              />
            </div>
            <Clock className="size-3.5" />
            <span>更新于：{updateDate}</span>
          </div>
        </div>

        {/* 运输超7天异常提醒横幅 */}
        {bannerVisible && (
          <ShipmentAlertBanner counts={counts} onClose={markAsRead} />
        )}

        {/* Festival Banner - mobile */}
        {festival.active && (
          <div
            className={`md:hidden px-4 py-2 text-center text-sm font-medium ${festival.textColor || ''}`}
            style={{
              backgroundColor: festival.textColor ? '#FEF2F2' : theme.primaryLight + '30',
            }}
          >
            {festival.icon && <span className="mr-1">{festival.icon}</span>}
            {festival.text || festival.name}
          </div>
        )}

        <main className="flex-1 overflow-y-auto pb-20 md:pb-0 relative z-10">
          <div className="px-4 md:px-6 py-5 max-w-6xl mx-auto">
            <ErrorBoundary
              FallbackComponent={({ error, resetErrorBoundary }) => (
                <div className="py-12 flex flex-col items-center justify-center text-center">
                  <div className="size-16 rounded-full bg-muted flex items-center justify-center mb-4">
                    <span className="text-3xl">⚠️</span>
                  </div>
                  <h3 className="text-base font-semibold mb-1 text-foreground">本页加载失败</h3>
                  <p className="text-sm text-muted-foreground mb-4 max-w-md">
                    {error instanceof Error ? error.message : String(error || '发生了未知错误')}
                  </p>
                  <p className="text-xs text-muted-foreground mb-4">
                    你仍可使用左侧菜单切换其它模块
                  </p>
                  <div className="flex gap-2">
                    <button
                      onClick={resetErrorBoundary}
                      className="px-4 py-2 rounded-md bg-primary text-primary-foreground text-sm font-medium hover:opacity-90 transition-opacity"
                    >
                      重试
                    </button>
                    <button
                      onClick={() => window.location.reload()}
                      className="px-4 py-2 rounded-md border border-border text-foreground text-sm font-medium hover:bg-muted transition-colors"
                    >
                      刷新页面
                    </button>
                  </div>
                </div>
              )}
              onError={(error) => {
                logger.error('页面渲染错误:', String(error));
              }}
              resetKeys={[location.pathname]}
            >
              <Outlet context={{ theme, festival, themeOverride, setThemeOverride, isLoggedIn, user, syncStatus }} />
            </ErrorBoundary>
          </div>
        </main>

        {/* 新设备登录安全提示 */}
        <NewDeviceAlert
          open={isNewDevice}
          onClose={dismissNewDevice}
          theme={theme}
        />
      </div>

      <BottomNav theme={theme} />
    </div>
  );
};
