// EXPORTS: Season, ThemeConfig, getSeason, getThemeConfig, getFestivalBadge

export type Season = 'spring' | 'summer' | 'autumn' | 'winter'

export interface PriorityColors {
  p0: string  // 重要且紧急（深色/高危）
  p1: string  // 重要不紧急（重点）
  p2: string  // 紧急不重要（主色）
  p3: string  // 不重要不紧急（浅色/低优）
}

export interface ThemeConfig {
  season: Season
  name: string
  primary: string
  primaryLight: string
  primaryDark: string
  bgGradient: string
  accent: string
  decorIcon1: string
  decorIcon2: string
  sidebarBg: string
  cardBg: string
  textAccent: string
  dividerGradient: string // 侧边栏分隔线渐变方向与主题配色
  dividerPattern: string  // 分隔线元素 emoji 组
  // 四象限优先级颜色（同色系深浅派生）
  priority: PriorityColors
  // UI 派生色
  ui: {
    cardBorder: string          // 卡片细边框色（主色10%透明）
    formulaCardBg: string       // 公式诊断卡片底色（主色5-8%透明）
    riskCardBg: string          // 风险警示卡片底色（P0色低透）
    riskCardBar: string         // 风险警示左侧竖条色（P0实色）
    glassBg: string             // 磨砂玻璃底色
    glassBorder: string         // 磨砂玻璃半透明边框
    glassShadow: string         // 磨砂玻璃柔光阴影
    topbarBg: string            // 顶部信息栏底色
    dividerLine: string         // 纤细分割线色
    badgeBg: string             // 徽章底色（主色低透）
  }
}

export interface FestivalBadge {
  active: boolean
  icon?: string
  text?: string
  textColor?: string
  name: string
}

