export function getSeason(month: number): Season {
  if (month >= 3 && month <= 5) return 'spring'
  if (month >= 6 && month <= 8) return 'summer'
  if (month >= 9 && month <= 11) return 'autumn'
  return 'winter'
}

export function getThemeConfig(season: Season): ThemeConfig {
  switch (season) {
    case 'spring': return springTheme
    case 'summer': return summerTheme
    case 'autumn': return autumnTheme
    case 'winter': return winterTheme
  }
}

export function getFestivalBadge(month: number, date: number, dayOfWeek: number): FestivalBadge {
  // 黑五：11月第四个星期五
  if (month === 11) {
    const firstDay = new Date(2024, 10, 1).getDay()
    const firstFriday = firstDay <= 5 ? 6 - firstDay : 6 - firstDay + 7
    const blackFriday = firstFriday + 21
    if (date >= blackFriday - 10 && date <= blackFriday + 10) {
      if (date === blackFriday) {
        return { active: true, icon: '🔥', text: '黑五当天', textColor: 'text-red-600', name: '黑五当天' }
      }
      return { active: true, text: '黑五促销季', textColor: 'text-red-600', name: '黑五促销季' }
    }
  }

  // 亚马逊会员日：7月第二个周二前后3天
  if (month === 7) {
    const firstDay = new Date(2024, 6, 1).getDay()
    const firstTuesday = firstDay <= 2 ? 2 - firstDay : 2 - firstDay + 7
    const secondTuesday = firstTuesday + 7
    if (date >= secondTuesday - 3 && date <= secondTuesday + 3) {
      return { active: true, icon: '⚠️', name: 'Prime Day' }
    }
  }

  // 返校季：8月15日-9月15日
  if ((month === 8 && date >= 15) || (month === 9 && date <= 15)) {
    return { active: true, icon: '🏫', name: '返校季' }
  }

  // 万圣节：10月25日-11月1日
  if ((month === 10 && date >= 25) || (month === 11 && date === 1)) {
    return { active: true, icon: '👻', name: '万圣节' }
  }

  // 圣诞节：12月20日-12月26日
  if (month === 12 && date >= 20 && date <= 26) {
    return { active: true, icon: '🎄', name: '圣诞节' }
  }

  return { active: false, name: '' }
}
