interface MonthlyReviewData {
  goals: string;
  insights: string;
  nextMonth: string;
}

function MonthlyReview({ theme }: { theme: ThemeConfig }) {
  const [now] = useState(() => new Date());
  const [currentMonth, setCurrentMonth] = useState({
    year: now.getFullYear(),
    month: now.getMonth(),
  });

  const [review, setReview] = useState<MonthlyReviewData>(() => {
    const key = `monthly-review:${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    try {
      const saved = scopedStorage.getItem(key);
      if (saved) return JSON.parse(saved);
    } catch { /* noop */ }
    return { goals: '', insights: '', nextMonth: '' };
  });

  const monthKey = `${currentMonth.year}-${String(currentMonth.month + 1).padStart(2, '0')}`;

  // 切换月份时加载对应数据
  useEffect(() => {
    const key = `monthly-review:${monthKey}`;
    try {
      const saved = scopedStorage.getItem(key);
      if (saved) {
        setReview(JSON.parse(saved));
      } else {
        setReview({ goals: '', insights: '', nextMonth: '' });
      }
    } catch {
      setReview({ goals: '', insights: '', nextMonth: '' });
    }
  }, [monthKey]);

  // 自动保存（防抖）
  useEffect(() => {
    const timer = setTimeout(() => {
      const key = `monthly-review:${monthKey}`;
      scopedStorage.setItem(key, JSON.stringify(review));
    }, 500);
    return () => clearTimeout(timer);
  }, [review, monthKey]);

  function prevMonth() {
    setCurrentMonth((prev) => {
      let m = prev.month - 1;
      let y = prev.year;
      if (m < 0) { m = 11; y--; }
      return { year: y, month: m };
    });
  }

  function nextMonth() {
    setCurrentMonth((prev) => {
      let m = prev.month + 1;
      let y = prev.year;
      if (m > 11) { m = 0; y++; }
      return { year: y, month: m };
    });
  }

  function updateReview(field: keyof MonthlyReviewData, value: string) {
    setReview((prev) => ({ ...prev, [field]: value }));
  }

  const isCurrentMonth =
    currentMonth.year === now.getFullYear() && currentMonth.month === now.getMonth();

  return (
    <Card
      className="border-0"
      style={{
        backgroundColor: theme.ui.glassBg,
        backdropFilter: 'blur(12px) saturate(180%)',
        WebkitBackdropFilter: 'blur(12px) saturate(180%)',
        boxShadow: theme.ui.glassShadow,
        border: `1px solid ${theme.ui.glassBorder || theme.ui.cardBorder}`,
      }}
    >
      <CardHeader className="pb-2">
        <div className="flex items-center gap-2">
          <Sparkles className="size-5" style={{ color: theme.primary }} />
          <CardTitle className="text-base">每月复盘</CardTitle>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex items-center gap-1 mb-4 justify-center">
          <Button
            variant="ghost"
            size="icon"
            className="h-7 w-7"
            onClick={prevMonth}
            aria-label="上个月"
          >
            <ChevronLeft className="size-4" />
          </Button>
          <span className="text-sm font-medium min-w-[80px] text-center">
            {currentMonth.year}年{currentMonth.month + 1}月
          </span>
          <Button
            variant="ghost"
            size="icon"
            className="h-7 w-7"
            onClick={nextMonth}
            aria-label="下个月"
          >
            <ChevronRight className="size-4" />
          </Button>
        </div>
        <p className="text-xs text-muted-foreground mb-3 text-center">
          {isCurrentMonth ? '本月重要事项提醒与心得感悟' : '查看历史月份的复盘记录'}
        </p>
        <div>
          <label className="text-xs font-medium text-foreground mb-1.5 block flex items-center gap-1">
            <Target className="size-3" style={{ color: theme.primary }} />
            本月事项提醒
          </label>
          <Textarea
            value={review.goals}
            onChange={(e) => updateReview('goals', e.target.value)}
            placeholder="本月有哪些重要事项、纪念日、deadline？"
            className="min-h-[70px] text-sm resize-none"
          />
        </div>

        <div>
          <label className="text-xs font-medium text-foreground mb-1.5 block flex items-center gap-1">
            <Lightbulb className="size-3 text-amber-500" />
            心得感悟
          </label>
          <Textarea
            value={review.insights}
            onChange={(e) => updateReview('insights', e.target.value)}
            placeholder="这个月有什么收获、成长或反思？"
            className="min-h-[70px] text-sm resize-none"
          />
        </div>

        <div>
          <label className="text-xs font-medium text-foreground mb-1.5 block flex items-center gap-1">
            <CalendarDays className="size-3 text-green-600" />
            下月事项提醒
          </label>
          <Textarea
            value={review.nextMonth}
            onChange={(e) => updateReview('nextMonth', e.target.value)}
            placeholder="下个月有什么重要事项提前记下来？"
            className="min-h-[70px] text-sm resize-none"
          />
        </div>

        <div className="text-[10px] text-muted-foreground text-center pt-1">
          内容自动保存到本地
        </div>
      </CardContent>
    </Card>
  );
}

