// ============ 灵感随笔 ============
interface InspirationItem {
  id: string;
  content: string;
  createdAt: number;
}

function InspirationNotes({ theme }: { theme: ThemeConfig }) {
  const [notes, setNotes] = useState<InspirationItem[]>(() => {
    try {
      const saved = scopedStorage.getItem('inspiration-notes');
      if (saved) return JSON.parse(saved);
    } catch { /* noop */ }
    return [];
  });
  const [input, setInput] = useState('');

  // 自动保存
  useEffect(() => {
    scopedStorage.setItem('inspiration-notes', JSON.stringify(notes));
  }, [notes]);

  function addNote() {
    if (!input.trim()) return;
    const newNote: InspirationItem = {
      id: `note-${Date.now()}`,
      content: input.trim(),
      createdAt: Date.now(),
    };
    setNotes((prev) => [newNote, ...prev]);
    setInput('');
    toast.success('已记录灵感 ✨');
  }

  function deleteNote(id: string) {
    setNotes((prev) => prev.filter((n) => n.id !== id));
  }

  function formatTime(ts: number): string {
    const d = new Date(ts);
    const now = new Date();
    const isToday = d.toDateString() === now.toDateString();
    if (isToday) {
      return `今天 ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
    }
    const yesterday = new Date(now);
    yesterday.setDate(yesterday.getDate() - 1);
    if (d.toDateString() === yesterday.toDateString()) {
      return `昨天 ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
    }
    return `${d.getMonth() + 1}/${d.getDate()} ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
  }

  return (
    <Card
      className="border-0"
      style={{
        backgroundColor: theme.ui.glassBg,
        backdropFilter: 'blur(12px) saturate(180%)',
        WebkitBackdropFilter: 'blur(12px) saturate(180%)',
        boxShadow: theme.ui.glassShadow,
        border: `1px solid ${theme.ui.glassBorder || theme.ui.cardBorder}`,
      }}
    >
      <CardHeader className="pb-2">
        <div className="flex items-center gap-2">
          <Lightbulb className="size-5" style={{ color: theme.primary }} />
          <CardTitle className="text-base">灵感随笔</CardTitle>
          <Badge
            className="text-xs border-0 ml-auto"
            style={{ backgroundColor: theme.ui.badgeBg, color: theme.primary }}
          >
            {notes.length}条
          </Badge>
        </div>
      </CardHeader>
      <CardContent className="space-y-3">
        {/* 输入区 */}
        <div className="space-y-2">
          <Textarea
            value={input}
            onChange={(e: ChangeEvent<HTMLTextAreaElement>) => setInput(e.target.value)}
            placeholder="有什么灵感或备忘？写下来吧..."
            className="min-h-[80px] text-sm resize-none"
            onKeyDown={(e) => {
              if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
                e.preventDefault();
                addNote();
              }
            }}
          />
          <div className="flex items-center justify-between">
            <span className="text-[10px] text-muted-foreground">
              支持多行 · Ctrl/Cmd + Enter 快速保存
            </span>
            <Button size="sm" style={{ backgroundColor: theme.primary }} onClick={addNote}>
              <Plus className="size-3.5 mr-1" />
              记录
            </Button>
          </div>
        </div>

        {/* 列表 */}
        {notes.length === 0 ? (
          <div className="text-center py-8 text-muted-foreground text-sm">
            还没有记录，写下第一条灵感吧～
          </div>
        ) : (
          <ScrollArea className="max-h-[320px]">
            <div className="space-y-2 pr-2">
              {notes.map((note) => (
                <div
                  key={note.id}
                  className="p-3 rounded-lg bg-muted/30 border border-border/40 group hover:bg-muted/50 transition-colors"
                >
                  <div className="flex items-start gap-2">
                    <p className="flex-1 text-sm whitespace-pre-wrap leading-relaxed">
                      {note.content}
                    </p>
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-6 w-6 text-muted-foreground hover:text-destructive opacity-0 group-hover:opacity-100 transition-opacity shrink-0"
                      onClick={() => deleteNote(note.id)}
                      aria-label="删除"
                    >
                      <Trash2 className="size-3.5" />
                    </Button>
                  </div>
                  <div className="text-[10px] text-muted-foreground mt-2 flex items-center gap-1">
                    <Clock className="size-3" />
                    {formatTime(note.createdAt)}
                  </div>
                </div>
              ))}
            </div>
          </ScrollArea>
        )}
      </CardContent>
    </Card>
  );
}

